from dataclasses import dataclass, field
from openfeature import api

TIER_CONTROLS = {
    "internal": {"owner", "validation", "vendor_contract"},
    "customer": {"owner", "validation", "vendor_contract", "disclosure",
                 "grievance", "incident_route", "kill_switch"},
    "decision": {"owner", "validation", "vendor_contract", "disclosure",
                 "grievance", "incident_route", "kill_switch", "human_review"},
}

@dataclass
class AISystem:
    name: str
    owner: str
    tier: str                      # internal, customer or decision
    vendor_model: str | None
    controls: set = field(default_factory=set)

    def gaps(self) -> set:
        return TIER_CONTROLS[self.tier] - self.controls

flags = api.get_client()

def run_agent(system: AISystem, request):
    if not flags.get_boolean_value(f"ai.{system.name}.enabled", False):
        return hand_to_human(request, reason="kill switch")     # stops without a deploy
    answer = system_agent(system).run(request)
    if system.tier == "decision":
        return queue_for_review(answer)                        # a human decides
    return answer + AI_DISCLOSURE
